package cn.lvxu.travel;
import android.app.*;import android.text.*;import android.widget.*;import java.time.*;import java.util.*;
final class SearchUi {
 private final MainActivity a;private final SearchIndex.Query query=new SearchIndex.Query();private final LinkedHashMap<String,SearchIndex.Result> selected=new LinkedHashMap<>();private LinearLayout results,quickTypes;private PageUi page;private EditText keyword;private int limit=50;
 SearchUi(MainActivity a){this.a=a;}
 void show(){page=new PageUi(a,"搜索与筛选");keyword=a.field(page.body,"搜索旅行、地点、预算、备注、清单或打卡",query.text,1);page.body.addView(a.text("快速切换类型",13,MainActivity.MUTED));quickTypes=a.row();HorizontalScrollView typeScroll=new HorizontalScrollView(a);typeScroll.setHorizontalScrollBarEnabled(false);typeScroll.addView(quickTypes);page.body.addView(typeScroll,new LinearLayout.LayoutParams(-1,-2));a.space(page.body,10);a.pair(page.body,a.action("筛选条件",false,this::filters),a.action("清除筛选",false,()->{query.tagId="";query.type="全部";query.from=query.to=null;query.after=query.before=null;query.minCost=query.maxCost=null;keyword.setText("");query.text="";selected.clear();refresh();}));a.pair(page.body,a.action("刷新结果",false,this::refresh),a.action("删除所选",false,this::deleteSelected));results=a.col();page.body.addView(results);keyword.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int b,int c){query.text=s.toString();limit=50;selected.clear();refresh();}public void afterTextChanged(Editable e){}});page.surface.getViewTreeObserver().addOnWindowFocusChangeListener(has->{if(has)refresh();});page.show();refresh();}
 private void filters(){LinearLayout f=a.col();Spinner type=a.select(f,"搜索范围",new String[]{"全部","旅行","行程","地点","预算","备注","清单","打卡"},query.type);ArrayList<TagRepository.Tag> tags=new ArrayList<>(new TagRepository(a).all());String[] labels=new String[tags.size()+1];labels[0]="全部标签";int old=0;for(int i=0;i<tags.size();i++){labels[i+1]=tags.get(i).name;if(tags.get(i).id.equals(query.tagId))old=i+1;}Spinner tag=a.select(f,"标签",labels,labels[old]);EditText from=a.field(f,"起始日期（YYYY-MM-DD，选填）",str(query.from),1),to=a.field(f,"结束日期（选填）",str(query.to),1),after=a.field(f,"每日开始时间（HH:mm，选填）",str(query.after),1),before=a.field(f,"每日结束时间（HH:mm，选填）",str(query.before),1),min=a.field(f,"最低花费 / 预算（元，选填）",query.minCost==null?"":Trip.money(query.minCost),8194),max=a.field(f,"最高花费 / 预算（元，选填）",query.maxCost==null?"":Trip.money(query.maxCost),8194);a.dialog("组合筛选",f,()->{try{LocalDate lo=date(from),hi=date(to);LocalTime l=time(after),h=time(before);Long low=money(min),high=money(max);if(lo!=null&&hi!=null&&lo.isAfter(hi)||l!=null&&h!=null&&l.isAfter(h)||low!=null&&high!=null&&low>high)throw new IllegalArgumentException();query.from=lo;query.to=hi;query.after=l;query.before=h;query.minCost=low;query.maxCost=high;query.type=type.getSelectedItem().toString();query.tagId=tag.getSelectedItemPosition()==0?"":tags.get(tag.getSelectedItemPosition()-1).id;selected.clear();refresh();}catch(Exception e){throw new IllegalArgumentException("请检查日期、时间和金额范围，起始值不能大于结束值");}},null);}
 private void refresh(){if(results==null)return;drawQuickTypes();results.removeAllViews();HashMap<String,String> names=new HashMap<>();for(TagRepository.Tag tag:new TagRepository(a).all())names.put(tag.id,tag.name);List<SearchIndex.Filter> filters=SearchIndex.activeFilters(query,names);if(!filters.isEmpty()){StringBuilder summary=new StringBuilder("当前筛选：");for(int i=0;i<filters.size();i++){if(i>0)summary.append(" · ");summary.append(filters.get(i).label);}results.addView(a.text(summary.toString(),13,MainActivity.INK));HorizontalScrollView clearScroll=new HorizontalScrollView(a);clearScroll.setHorizontalScrollBarEnabled(false);LinearLayout clears=a.row();for(SearchIndex.Filter filter:filters){TextView clear=a.action("清除"+filter.clearLabel,false,()->{SearchIndex.clear(query,filter.key);if("text".equals(filter.key))keyword.setText("");selected.clear();refresh();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);if(clears.getChildCount()>0)p.leftMargin=a.dp(8);clears.addView(clear,p);}clearScroll.addView(clears);results.addView(clearScroll,new LinearLayout.LayoutParams(-1,-2));a.space(results,8);}List<SearchIndex.Result> found=SearchIndex.search(a.trips,query);results.addView(a.text(found.size()+" 条结果",13,MainActivity.MUTED));if(found.isEmpty()){results.addView(a.text(SearchIndex.emptyMessage(query),14,MainActivity.MUTED));return;}String group="";int shown=0;for(SearchIndex.Result r:found){if(shown++>=limit)break;if(!group.equals(r.type)){group=r.type;results.addView(a.bold(group,17,MainActivity.INK));}LinearLayout c=a.card(results);CheckBox box=new CheckBox(a);box.setText(r.title);box.setTextColor(MainActivity.INK);box.setChecked(selected.containsKey(r.key()));box.setOnCheckedChangeListener((v,on)->{if(on)selected.put(r.key(),r);else selected.remove(r.key());});c.addView(box);c.addView(a.text(r.detail,13,MainActivity.MUTED));a.pair(c,a.action("打开 / 修改",false,()->a.openSearchResult(r)),a.action("删除",false,()->a.confirm("删除这条"+r.type+"记录？",()->{remove(r);a.changed();selected.remove(r.key());refresh();})));}if(found.size()>limit)results.addView(a.action("加载更多结果",false,()->{limit+=50;refresh();}));}
 private void drawQuickTypes(){if(quickTypes==null)return;quickTypes.removeAllViews();for(String type:new String[]{"全部","旅行","地点","预算","清单","打卡"}){TextView button=a.action(type,type.equals(query.type),()->{query.type=type;limit=50;selected.clear();refresh();});button.setContentDescription("类型："+type);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(a.dp(76),-2);if(quickTypes.getChildCount()>0)p.leftMargin=a.dp(8);quickTypes.addView(button,p);}}
 private void deleteSelected(){if(selected.isEmpty()){a.toast("请先选择要删除的内容");return;}ArrayList<SearchIndex.Result> batch=new ArrayList<>(selected.values());a.confirm("删除所选的 "+batch.size()+" 条记录？此操作不可撤销。",()->{for(SearchIndex.Result r:batch)remove(r);selected.clear();a.changed();refresh();});}
 private void remove(SearchIndex.Result r){for(Trip t:new ArrayList<>(a.trips))if(t.id.equals(r.tripId)){if("旅行".equals(r.type)){a.trips.remove(t);if(a.active==t)a.active=a.trips.isEmpty()?null:a.trips.get(0);}else if("地点".equals(r.type))t.stops.removeIf(s->s.id.equals(r.itemId));else if("预算".equals(r.type))t.expenses.removeIf(s->s.id.equals(r.itemId));else if("清单".equals(r.type))t.items.removeIf(s->s.id.equals(r.itemId));else if("打卡".equals(r.type))t.checkins.removeIf(s->s.id.equals(r.itemId));}}
 private static String str(Object o){return o==null?"":o.toString();}private static String value(EditText e){return e.getText().toString().trim();}private static LocalDate date(EditText e){return value(e).isEmpty()?null:LocalDate.parse(value(e));}private static LocalTime time(EditText e){return value(e).isEmpty()?null:LocalTime.parse(value(e));}private static Long money(EditText e){return value(e).isEmpty()?null:Trip.cents(value(e));}
}
